import type { BrandLogo } from "../icons/brandLogos";
import { LOCAL_ICON_SET } from "../icons/localSet";

/**
 * The mark each catalogue driver is drawn with: the database's own logo, wherever a connection or a
 * driver is listed.
 *
 * It used to be a Lucide shape per engine (a fish for MySQL, waves for MariaDB, a ring for Oracle)
 * and two letters on a wash of brand colour for the fifty-odd drivers beyond those ten — stand-ins
 * chosen so no trademark was redrawn by hand. The user asked for the real marks instead ("en vez de
 * nombres abreviados o iconos inventados, los iconos reales de cada uno"), and the answer
 * `icons/brandLogos.ts` already gave for the AI engines holds here too: copy the official geometry
 * from a set whose licence allows it, never approximate it.
 *
 * **Where each one comes from** is noted on its entry:
 * - `logos:*` — `@iconify-json/logos` (gilbarbara/logos, CC0-1.0), the set the file-icon picker
 *   loads. Databricks' is from a newer release of the same set than the installed one.
 * - `vscode-icons:*` — `@iconify-json/vscode-icons` (MIT), installed too.
 * - `devicon:*` (MIT), `thesvg-color:*` (theSVG, MIT), `simple-icons:*` (CC0-1.0), `carbon:*` (IBM,
 *   Apache-2.0), `gcp:*` (Google Cloud, Apache-2.0) and `tabler:*` (MIT) — sets this app does not
 *   install; the one entry each copied verbatim, the way Azure DevOps was in `brandLogos.ts`.
 * - The rest — products no set ships a mark for — from the vendor's or the project's own artwork,
 *   the same exception `icons/localSet.ts` records for IRIS: an explicit request, naming the product
 *   whose rows it marks. Two of those exist only as rasters (Derby's hat, HyperSQL's "Q") and are
 *   embedded as such.
 *
 * All of them are listed in THIRD-PARTY-NOTICES.md. A licence on a drawing does not cover the brand:
 * the marks stay their owners' trademarks, used only to say which database a row is.
 *
 * **Edited only where its entry says**, and only for one of three reasons: a wordmark cut down to its
 * symbol (16px cannot carry letters), a dark ink that vanished on a dark sheet (see `ink`), or a
 * one-colour glyph given its brand's colour. Products sold under their maker's mark wear it: SAP ASE
 * (Sybase) and HANA are SAP's, OpenEdge is Progress's.
 *
 * **Only the database workspace pays for them.** This module is imported by `components/db/DbLogo.tsx`
 * alone — not by `dbChrome.tsx`, which the Agents and Stories views import for its toolbar button —
 * so its ~115 KB of markup lands in the chunk that opens a database, not in the app's start.
 *
 * To add one: copy `body`, `width` and `height` from the source (Iconify's `/<set>.json?icons=<name>`
 * answers with exactly those), file it in `DB_LOGOS` under the catalogue id, and run `logos.test.ts`,
 * which refuses a catalogue driver without a mark and a body that could do anything but draw.
 */
export interface DbLogo extends BrandLogo {
  /**
   * What the mark's `currentColor` parts are painted on a light sheet: the brand's own dark ink. On a
   * dark sheet they take the text colour instead — which is what these brands do on a dark
   * background themselves (MySQL's dolphin, InfluxDB's cube and Elastic's middle bar all turn
   * white). Without one, those parts follow the text colour on both sheets, which is right for the
   * marks whose dark part is plain black: Postgres' outline, Hive's, Vertica's V, Derby's hat.
   */
  ink?: string;
}

