/**
 * InterSystems IRIS: the bracket `icons/localSet.ts` draws for `.cls` files — the user-supplied
 * artwork noted there — with its indigo moved to `ink`, since on a dark sheet that ribbon all but
 * disappeared.
 */
const IRIS: DbLogo = {
  width: LOCAL_ICON_SET.width ?? 13,
  height: LOCAL_ICON_SET.height ?? 32,
  ink: "#2e3192",
  body: LOCAL_ICON_SET.icons.iris.body.replace('fill="#2e3192"', 'fill="currentColor"'),
};

/**
 * Every catalogue driver's mark, by driver id. The drivers of one product share it — the four SQL
 * Server drivers, both Derby modes, the three Db2 ones. A driver the user added is not here: it has
 * no brand, and `components/db/DbLogo.tsx` draws its initials.
 */
export const DB_LOGOS: Readonly<Record<string, DbLogo>> = {
  postgresql: POSTGRESQL,
  supabase: SUPABASE,
  "aurora-postgresql": AWS_AURORA,
  cockroachdb: COCKROACHDB,
  greenplum: GREENPLUM,
  yugabytedb: YUGABYTEDB,
  mysql: MYSQL,
  "aurora-mysql": AWS_AURORA,
  tidb: TIDB,
  "singlestore-mysql": SINGLESTORE,
  mariadb: MARIADB,
  sqlserver: SQL_SERVER,
  "azure-sql": AZURE_SQL,
  "azure-synapse": AZURE,
  sqlite: SQLITE,
  mongodb: MONGODB,
  documentdb: AWS_DOCUMENTDB,
  redis: REDIS,
  oracle: ORACLE,
  iris: IRIS,
  "oracle-legacy": ORACLE,
  redshift: AWS_REDSHIFT,
  athena: AWS_ATHENA,
  dynamodb: AWS_DYNAMODB,
  cassandra: CASSANDRA,
  "derby-embedded": DERBY,
  "derby-remote": DERBY,
  hive: HIVE,
  spark: SPARK,
  clickhouse: CLICKHOUSE,
  couchbase: COUCHBASE,
  exasol: EXASOL,
  bigquery: BIGQUERY,
  "h2": H2,
  "hsqldb-local": HSQLDB,
  "hsqldb-remote": HSQLDB,
  "db2": DB2,
  "db2-legacy": DB2,
  "db2-jtopen": DB2,
  informix: INFORMIX,
  "sqlserver-jdbc": SQL_SERVER,
  "sqlserver-jtds": SQL_SERVER,
  "sqlserver-localdb": SQL_SERVER,
  snowflake: SNOWFLAKE,
  "sybase-jtds": SAP,
  "sybase-jconnect": SAP,
  vertica: VERTICA,
  trino: TRINO,
  presto: PRESTO,
  databricks: DATABRICKS,
  ignite: IGNITE,
  phoenix: PHOENIX,
  "phoenix-thin": PHOENIX,
  denodo: DENODO,
  duckdb: DUCKDB,
  elasticsearch: ELASTICSEARCH,
  firebird: FIREBIRD,
  spanner: SPANNER,
  influxdb: INFLUXDB,
  mimer: MIMER,
  openedge: PROGRESS,
  saphana: SAP,
  singlestore: SINGLESTORE,
  tarantool: TARANTOOL,
  teradata: TERADATA,
  tibero: TIBERO,
};

/** A driver's mark, or `null` for one the catalogue doesn't know (a driver the user added). */
export function dbLogo(driverId: string): DbLogo | null {
  return Object.prototype.hasOwnProperty.call(DB_LOGOS, driverId) ? DB_LOGOS[driverId] : null;
}
